import { useState } from "react";
import { Meta, StoryObj } from "@storybook/react";
import { action } from "storybook/actions";
import Calendar from "./calendar";
import { createDate } from "@/core/helpers";
import { Matcher } from "react-day-picker";

const FAKE_START_DATE = "2023-05-10";
const FAKE_DISABLED_DATE = "2023-05-20";
const FAKE_END_DATE = "2023-06-27";

const meta = {
  title: "Primitives/Calendar/Calendar",
  component: Calendar,
  args: {
    startDate: createDate(FAKE_START_DATE),
    endDate: createDate(FAKE_END_DATE),
    selectedDate: [createDate(FAKE_START_DATE)],
    disabledDates: [createDate(FAKE_DISABLED_DATE)],
    showOutsideDays: false,
    changeDate: action("Clicked date"),
    currentDisplayedMonth: createDate(FAKE_START_DATE),
    changedMonth: action("Changed month"),
  },
} satisfies Meta<typeof Calendar>;

export default meta;
export const Primary: StoryObj<typeof meta> = {
  render: function CalendarStory(args) {
    const [selectedDate, setSelectedDate] = useState<Matcher | undefined>(args.selectedDate);
    const [selectedMonth, setSelectedMonth] = useState(args.currentDisplayedMonth);
    return (
      <Calendar
        {...args}
        selectedDate={selectedDate}
        currentDisplayedMonth={selectedMonth}
        changeDate={(x) => {
          args.changeDate(x);
          setSelectedDate(x);
        }}
        changedMonth={(x) => {
          args.changedMonth(x);
          setSelectedMonth(x);
        }}
      />
    );
  },
};
